components.css:
.ds-primary{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;font-size:13px;font-weight:500;line-height:1.3;min-height:34px;padding:7px 10px;border:1px solid transparent;border-radius:9px;cursor:pointer;transition:background-color 160ms cubic-bezier(.16,1,.3,1),color 160ms cubic-bezier(.16,1,.3,1),box-shadow 160ms cubic-bezier(.16,1,.3,1),transform 160ms cubic-bezier(.16,1,.3,1);color:#FFFFFF;background:linear-gradient(#0877D8,#0865D3);box-shadow:inset 0 1px #7DBBFA,0 2px 4px #245EA729;}.ds-primary:hover{background:linear-gradient(#0877D8,#086AD4);}.ds-primary:focus-visible{outline:2px solid var(--color-primary,#0066D6);outline-offset:3px;}.ds-primary:active:not(:disabled){transform:translateY(1px);}.ds-primary:disabled{opacity:.45;cursor:default;}@media(prefers-reduced-motion:reduce){.ds-primary{transition:none;}}
.ds-primary{background: var(--color-primary);color: white;background: linear-gradient(#0877D8,#0865D3);box-shadow: inset 0 1px #7DBBFA, 0 2px 4px #245EA729;background: linear-gradient(#0872D4,#0965CB);box-shadow: inset 0 1px #FFFFFF66, 0 2px 4px #245EA724;}
.ds-primary:hover{background: #1838B8;background: linear-gradient(#0877D8,#086AD4);}
